using System.Text.Encodings.Web;
using System.Text.Json;
using Babel.Api.Endpoints;
using Babel.Contracts.Posting;
using Babel.Core.CapabilityProfile;
using Babel.Core.Access;
using Babel.Core.CompanySetup;
using Babel.SharedKernel;

namespace Babel.Api.OpenApi;

/// <summary>
/// مولّد وثيقة العقد المنشور.
/// <para>
/// <b>الحتمية هي كل شيء هنا.</b> وثيقة تتغيّر بايتاتها بين تشغيلين تجعل حارس الانحراف
/// عديم القيمة — <b>وأسوأ من ذلك: تجعله يبدو عاملاً</b>. ولذلك كل مصدر لاحتمالية
/// مُغلق صراحةً:
/// </para>
/// <list type="bullet">
///   <item><description>لا طابع زمني، ولا إصدار تجميعة، ولا اسم جهاز، ولا معرّف بناء.</description></item>
///   <item><description>لا قاموس يُكتب بترتيب تعدّاده: كل مجموعة تُكتب من قائمة مرتَّبة صراحةً بـ<c>StringComparer.Ordinal</c>.</description></item>
///   <item><description>لا فرز ثقافي: <c>Ordinal</c> في كل موضع — الفرز الثقافي يختلف بين <c>tr-TR</c> و<c>en-US</c> على الحروف نفسها.</description></item>
///   <item><description>سطر جديد مثبَّت <c>\n</c>، ومسافة بادئة مثبَّتة، ومُرمِّز مثبَّت، وبلا علامة ترتيب بايتات.</description></item>
///   <item><description>قوائم أعضاء التعدادات تُقرأ من التعداد نفسه بترتيب إعلانه — لا نصّاً مكتوباً بيد ينحرف عنه.</description></item>
/// </list>
/// <para>
/// <b>وحارس ثانٍ داخل المولّد نفسه:</b> قبل الكتابة يُقارَن ما وثّقناه بما سجّله التطبيق
/// فعلاً من مسارات وأفعال. اختلافٌ في أي اتجاه يُفشل التوليد — فلا يمكن أن يُودَع عقد
/// يصف باباً غير موجود، ولا أن يوجد باب غير موصوف.
/// </para>
/// </summary>
internal static class OpenApiEmitter
{
    /// <summary>إصدار مواصفة OpenAPI المُستعمل.</summary>
    public const string SpecVersion = "3.1.0";

    private static readonly JsonWriterOptions WriterOptions = new()
    {
        Indented = true,
        IndentCharacter = ' ',
        IndentSize = 2,
        NewLine = "\n",
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        SkipValidation = false,
    };

    /// <summary>يولّد الوثيقة بايتات UTF-8 بلا علامة ترتيب بايتات.</summary>
    /// <param name="registeredOperations">
    /// ما سجّله التطبيق فعلاً: (المسار، الفعل). يُقارَن بما توثّقه هذه الوثيقة.
    /// </param>
    public static byte[] Emit(IReadOnlyCollection<(string Path, string Method)> registeredOperations)
    {
        ArgumentNullException.ThrowIfNull(registeredOperations);

        CrossCheck(registeredOperations);

        using MemoryStream stream = new();
        using (Utf8JsonWriter writer = new(stream, WriterOptions))
        {
            WriteDocument(writer);
        }

        // سطر أخير: ملف نصّي مُودَع في git ينتهي بسطر جديد، وإلا أظهر كل فرق سطراً زائفاً.
        stream.Write("\n"u8);
        return stream.ToArray();
    }

    /// <summary>
    /// كل عملية توثّقها هذه الوثيقة: المسار والفعل ومعرّفها.
    /// <b>مرتَّبة صراحةً</b> — لا بترتيب كتابتها في هذا الملف.
    /// </summary>
    private static IReadOnlyList<Operation> Operations { get; } =
    [
        .. new List<Operation>
        {
            new(ApiRoutes.Health, "get", "health",
                "حالة الخدمة وثقافتها", "Service health and culture",
                "تُرجع حالة الخدمة، وثقافة العملية وتقويمها الافتراضي. خارج المصادقة وخارج نطاق الشركة.",
                "Returns service status plus the process culture and its default calendar. Unauthenticated and outside company scope.",
                Body: null, Response: "HealthResponse", Success: 200, Query: []),

            new(ApiRoutes.OpenApiDocument, "get", "readPublishedContract",
                "العقد المنشور نفسه", "The published contract itself",
                "يخدم بايتات contracts/openapi/v1.json **كما أُودعت** — مضمَّنةً في التجميعة وقت البناء. "
                + "ولا تُبنى وثيقة وقت التشغيل: الوثيقة تُولَّد بـ--emit-openapi وتُودَع ويحرسها PublishedContractTests "
                + "بايتاً بايت، ويحرس Rule18 العميلَ المُولَّد مقابلها. وخادمٌ يبني وثيقةً ثالثة عند كل طلب يضع طرفاً "
                + "خارج الحارسَين، وواجهةٌ تعرض عقداً لم يولّده أحد تبدو مرجعاً وهي خطأ — وهو فخ-84 من بابه الثالث. "
                + "وهذا الباب بلا اعتماد: محتواه ملفٌّ مُودَع في المستودع، ولا يحمل بيانات مستأجر واحد.",
                "Serves the bytes of contracts/openapi/v1.json **exactly as committed**, embedded into the assembly at build time. "
                + "No document is built at runtime: the document is generated by --emit-openapi, committed, guarded byte for byte by "
                + "PublishedContractTests, and the generated client is guarded against it by Rule18. A server that builds a third document "
                + "per request puts a side outside both guards, and a docs page showing a contract nobody generated looks authoritative and "
                + "is wrong — فخ-84 by its third door. This path is anonymous: its content is a file committed in the repository, and it "
                + "carries no tenant data whatsoever.",
                Body: null, Response: string.Empty, Success: 200, Query: [],
                ResponseMediaType: "application/json", ResponseInlineType: "object"),

            new(ApiRoutes.Docs, "get", "readDocsPage",
                "صفحة استعراض العقد", "The contract browser page",
                "صفحة HTML **قائمة بذاتها بالكامل**: لا خطّ خارجي ولا نصّ برمجي من شبكة توصيل ولا صورة بعيدة. "
                + "تقرأ /openapi/v1.json من الخادم نفسه وتعرض مساراته ومخطّطاته، وفيها زرّ «جرّب» يُصدر طلباً حقيقياً. "
                + "والاعتماد الذي يُكتب فيها يبقى في ذاكرة الصفحة وحدها — لا في localStorage ولا في عنوان ولا في ملفّ ارتباط — "
                + "و**لا رمز مطبوع فيها**: تُخدَم بايتاتها نفسها لكل طالب. والطلب الذي تُصدره يمرّ بالمصادقة والنطاق "
                + "والاستحقاق كأي عميل، فشركةٌ خارج نطاق الاعتماد تُرفض بـ403 tenancy.company_out_of_scope منها كما تُرفض من curl.",
                "A **fully self-contained** HTML page: no external font, no script from a delivery network, no remote image. It reads "
                + "/openapi/v1.json from this same server and renders its paths and schemas, with a Try-it button that issues a real request. "
                + "A credential typed into it stays in the page's memory alone — not in localStorage, not in a URL, not in a cookie — and "
                + "**no token is baked into it**: the same bytes are served to every caller. The request it issues passes through authentication, "
                + "scope, and entitlement like any client, so a company outside the credential's scope is refused with "
                + "403 tenancy.company_out_of_scope from the page exactly as it is from curl.",
                Body: null, Response: string.Empty, Success: 200, Query: [],
                ResponseMediaType: "text/html", ResponseInlineType: "string"),

            new(ApiRoutes.Session, "get", "readSession",
                "الجلسة: الهوية والشركات المبلوغة", "The session: identity and reachable companies",
                "يُرجع من يقف خلف الاعتماد — المستأجر والمستخدم — و**الشركات التي يبلغها هذا الاعتماد بأسمائها**. "
                + "وهذه أول نقطة يناديها عميل: معرّف الشركة إلزامي في كل مسار آخر وهو معرّف بصيغة 8-4-4-4-12، "
                + "ولا يستطيع إنسان أن يكتبه — فيُختار من هنا ولا يُكتب.\n\n"
                + "والاسم العربي هو السجلّ وnameTranslations ترجماته أيّاً كان عددها (ADR-0021)؛ ولا حقل ثابت "
