                + "بـRFC 5987 كي يبقى الاسم العربي عربياً.",
                "Returns the attachment bytes **after the store recomputes the digest and compares it with the recorded one**. A file swapped "
                + "under the same path is **refused here and never served**: a store that serves and then tells you it did not match has already "
                + "served it.\n\n"
                + "**The order is declared:** the ticket signature is verified, then its expiry, then **its tenant is compared with the session's "
