                + "نقطة الضبط لكل قسيمة وصفَّ محاولةٍ واحداً في جدول الوحدة لكل قسيمة. ولو رُحِّل المسيّر قيداً واحداً "
                + "لصار الطرفان بحبيبيّتين مختلفتين ولاستحال هذا الباب.\n\n"
