                    new Refusal(409, "لا خطوة تنتظر تأكيداً بهذا المعرّف.", "No step awaits confirmation under this identifier."),
                    new Refusal(503, "الوكيل غير مركَّب على هذا الخادم.", "The agent is not composed on this server."),
