                + "approver**: the benefit formula and its bands are unverified and are not invented here. What the module computes "
                + "is the provision balance alone, and then the shortfall and the excess — both arithmetic derivations from two "
                + "numbers.");
            w.WriteStartObject("properties");
            WriteStringProperty(w, "employmentId", "علاقة العمل المنتهية.", "The terminated employment.", 36);
            WriteStringProperty(w, "measurementRef", "مرجع أساس الحساب المعتمد.", "The approved calculation basis reference.", 400);
            WriteStringProperty(w, "number", "رقم المخالصة.", "The settlement number.", 64);
            WriteDateProperty(w, "settledOn", "تاريخ المخالصة", "The settlement date.");
            WriteRefProperty(w, "settlementDue", "Money");
            WriteEnumProperty(w, "settlementMethod", "طريقة الصرف.", "The disbursement method.", SettlementMethodNames);
            WriteStringProperty(w, "treasuryPartyId", "طرف الخزينة — إلزامي.", "The treasury party — mandatory.", 64);
            w.WriteEndObject();
            WriteRequired(w, "employmentId", "measurementRef", "number", "settledOn", "settlementDue", "settlementMethod", "treasuryPartyId");
            w.WriteBoolean("additionalProperties", false);
        });

        yield return ("HrSettlement", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "المخالصة كما تخرج من السطح، **والسيناريو المنطبق مُسمّى** لا مستنتَجاً من فرق مبلغين. والمتطابقة "
                + "المعلَنة في المصفوفة مفروضة في قاعدة البيانات: provisionUtilised = amountPaid − shortfall + excess. / "
                + "The settlement as the surface returns it, **with the applicable scenario named** rather than inferred from the "
                + "difference of two amounts. The identity declared in the matrix is enforced in the database: "
                + "provisionUtilised = amountPaid − shortfall + excess.");
            w.WriteStartObject("properties");
            WriteBooleanProperty(w, "alreadyPosted", "هل كانت مُرحَّلة قبل هذا النداء؟", "Was it already posted before this call?");
            WriteRefProperty(w, "amountPaid", "Money");
            WriteStringProperty(w, "employeeCode", "الرمز المعتم.", "The opaque code.", 64);
            WriteStringProperty(w, "employmentId", "علاقة العمل.", "The employment.", 36);
            WriteNullableStringProperty(w, "entryId", "معرّف القيد إن رُحّلت، أو null.", "The entry identifier if posted, or null.", 36);
            WriteRefProperty(w, "excess", "Money");
            WriteStringProperty(w, "id", "المعرّف.", "The identifier.", 36);
            WriteStringProperty(w, "measurementRef", "مرجع أساس الحساب المعتمد.", "The approved calculation basis reference.", 400);
            WriteStringProperty(w, "number", "الرقم.", "The number.", 64);
            WriteRefProperty(w, "provisionBalance", "Money");
            WriteRefProperty(w, "provisionUtilised", "Money");
            WriteEnumProperty(w, "scenarioCode",
                "السيناريو المنطبق بأسماء المصفوفة نفسها: مطابق، أو ناقص فيُحمَّل العجز على مصروف الفترة، أو زائد فتُردّ الزيادة إليه.",
                "The applicable scenario under the matrix's own names: exact, short with the shortfall charged to the period expense, or excess with the surplus released back to it.",
                EndOfServiceScenarioCodes);
            WriteDateProperty(w, "settledOn", "تاريخ المخالصة", "The settlement date.");
            WriteRefProperty(w, "settlementDue", "Money");
            WriteEnumProperty(w, "settlementMethod", "طريقة الصرف.", "The disbursement method.", SettlementMethodNames);
            WriteRefProperty(w, "shortfall", "Money");
            WriteStringProperty(w, "state", "الحالة.", "The state.", 16);
            WriteStringProperty(w, "treasuryPartyId", "طرف الخزينة.", "The treasury party.", 64);
            w.WriteEndObject();
            WriteRequired(w, "alreadyPosted", "amountPaid", "employeeCode", "employmentId", "entryId", "excess", "id", "measurementRef", "number", "provisionBalance", "provisionUtilised", "scenarioCode", "settledOn", "settlementDue", "settlementMethod", "shortfall", "state", "treasuryPartyId");
            w.WriteBoolean("additionalProperties", false);
        });

        yield return ("HrReconciliationDivergence", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "سطر انحراف واحد — **بحبيبيّة المستند والطرف معاً**. و`documentId` على قيود الاستحقاق هو معرّف "
                + "القسيمة، وهو ما يجعل الطرفين متساويي الحبيبيّة فتمكن المقارنة أصلاً. / "
                + "A single divergence row — **at the grain of the document and the party together**. On accrual entries "
                + "`documentId` is the payslip's identifier, which is what makes the two sides share one grain so the comparison is "
                + "possible at all.");
            w.WriteStartObject("properties");
            WriteRefProperty(w, "controlEffect", "Money");
            WriteRefProperty(w, "divergence", "Money");
            WriteStringProperty(w, "documentId", "معرّف المستند كما أرسلته الوحدة إلى الدفتر.",
                "The document identifier as the module sent it to the ledger.", 64);
            WriteStringProperty(w, "documentType", "نوع المستند كما أرسلته الوحدة.", "The document type as the module sent it.", 64);
            WriteStringProperty(w, "partyId", "الرمز المعتم للموظف — وهو كل ما يعرفه الدفتر عنه.",
                "The employee's opaque code — all the ledger knows of them.", 64);
            WriteEnumProperty(w, "reasonCode", "سبب الانحراف.", "The divergence reason.", DivergenceReasonCodes);
            WriteRefProperty(w, "subledgerEffect", "Money");
            w.WriteEndObject();
            WriteRequired(w, "controlEffect", "divergence", "documentId", "documentType", "partyId", "reasonCode", "subledgerEffect");
            w.WriteBoolean("additionalProperties", false);
        });

        yield return ("HrReconciliation", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "تقرير مطابقة دفتر الموظف — **ولا رقم فيه اسمه «رصيد الموظف»، وهذا قرارٌ لا نقص**. قارئ نقطة الضبط "
                + "يجمّع بلا تفصيل بالحساب ويعيد صافياً واحداً، ودفتر الموظف يمتدّ على أصلٍ واحد وثلاثة خصوم — فصافٍ "
                + "واحد يقاصّ سلفةً بمخصص خدمة براتب مستحق ويعلن التطابق وهو أعمى. / "
                + "The employee subledger reconciliation report — **and it publishes no single number called 'the employee's "
                + "balance'; a decision, not a gap**. The control point reader aggregates without account detail and returns one "
                + "net, while the employee subledger spans one asset and three liabilities — so one net offsets an advance against "
                + "a service provision against a salary payable and declares agreement while blind.");
            w.WriteStartObject("properties");
            WriteDateProperty(w, "asOf", "تاريخ المطابقة", "The reconciliation date.");
            WriteArrayRefProperty(w, "divergences", "HrReconciliationDivergence",
                "المستندات المسؤولة عن الفارق وحدها، مرتَّبة ترتيباً ثابتاً.",
                "Only the documents responsible for the difference, in a stable order.");
            WriteBooleanProperty(w, "isReconciled", "هل خلا التقرير من أي انحراف؟ **لا «قريب من الصفر»**.",
                "Is the report free of any divergence? **Not 'close to zero'**.");
            WriteIntegerProperty(w, "matchedDocuments", 0, int.MaxValue,
                "عدد المستندات التي تطابق طرفاها بالضبط — وهو ما يمنع «صفر انحراف» من أن يعني «لم يُفحص شيء».",
                "The number of documents whose two sides matched exactly — which is what stops 'zero divergences' from meaning 'nothing was checked'.");
            w.WriteEndObject();
            WriteRequired(w, "asOf", "divergences", "isReconciled", "matchedDocuments");
            w.WriteBoolean("additionalProperties", false);
        });
    }

    /// <summary>
    /// أسماء حالات الاستحقاق كما تُقرأ على السلك — <b>من التعداد نفسه لا مكتوبةً بيد</b>.
    /// <para>ولا يُكتب هنا اسمٌ منها حرفياً: قائمةٌ مكتوبة بيد تنحرف عن التعداد عند أول
    /// حالة رابعة، فيصف العقدُ مجموعةً مغلقة ليست مغلقة.</para>
    /// </summary>
    private static readonly string[] EntitlementStateNames = Enum.GetNames<Babel.Core.Entitlement.EntitlementState>();

    /// <summary>
    /// أسماء أطوار الدور وحالات الخطوة وأشكال الحدث على السلك.
    /// <para>
    /// <b>مقروءةٌ من التعدادات نفسها لا مكتوبةً هنا</b>: قائمةٌ ثانية بيدٍ تنحرف عند أوّل
    /// عضوٍ يُضاف، فيصف العقد حالةً لا وجود لها — أو يسكت عن حالةٍ تصل إلى اللوحة فلا
    /// تعرفها. والتحويل إلى الحرف الصغير الأوّل هو اصطلاح هذا السطح نفسه.
    /// </para>
    /// <para>
    /// <b>ولاحظ ما ليس في أيٍّ منها ولا يمكن أن يكون: <c>posted</c>.</b> لا عضو بهذا
    /// الاسم في <c>AgentStepState</c> ولا في <c>AgentTurnPhase</c>، فالعقد المنشور عاجزٌ
    /// عن وصف حالةِ ترحيلٍ في مسار الوكيل — <b>لا لأنّا حذفناها، بل لأنها غير موجودة</b>.
    /// </para>
    /// </summary>
    private static readonly string[] AgentStepStateNames =
        [.. Enum.GetNames<Babel.Ai.Workspace.AgentStepState>().Select(Wire).Order(StringComparer.Ordinal)];

    /// <summary>أطوار الدور — مقروءةً من التعداد.</summary>
    private static readonly string[] AgentTurnPhaseNames =
        [.. Enum.GetNames<Babel.Ai.Workspace.AgentTurnPhase>().Select(Wire).Order(StringComparer.Ordinal)];

    /// <summary>أشكال حدث الدور — مقروءةً من التعداد.</summary>
    private static readonly string[] AgentTurnEventKindNames =
        [.. Enum.GetNames<Babel.Ai.Agent.AgentTurnEventKind>().Select(Wire).Order(StringComparer.Ordinal)];

    /// <summary>اسمُ عضوٍ على السلك: أوّلُه صغير وما بعده كما هو.</summary>
    private static string Wire(string member) =>
        char.ToLowerInvariant(member[0]) + member[1..];

    /// <summary>حالات الاشتراك كما يقيّدها <c>ck_sub_state</c> في مخطّط مستوى التحكّم.</summary>
    private static readonly string[] SubscriptionStateNames = ["Active", "Lapsed", "Cancelled"];

    /// <summary>حالات المستأجر في سجل الأسطول — من التعداد نفسه.</summary>
    private static readonly string[] TenantStatusNames =
        Enum.GetNames<Babel.ControlPlane.Registry.TenantStatus>();

    /// <summary>مفتاح الطلب على السلك: قيمة عشوائية يولّدها العميل ويحتفظ بها.</summary>
    private static void WriteSignupKeyProperty(Utf8JsonWriter w)
    {
        w.WriteStartObject("requestKey");
        w.WriteString("type", "string");
        w.WriteNumber("minLength", Fleet.SignupIdentity.MinimumKeyLength);
        w.WriteNumber("maxLength", Fleet.SignupIdentity.MaximumKeyLength);
        w.WriteString("description",
            "مفتاح الطلب: قيمة **عشوائية** يولّدها العميل ويحتفظ بها، ومنها تُشتقّ كل معرّفات التسجيل اشتقاقاً "
            + "حتمياً. فإعادةُ الإرسال به تردّ المستأجر نفسه ولا تُنشئ ثانياً — ومفتاحٌ قصير يصير تخمينُه ممكناً. / "
            + "The request key: a **random** value the client generates and keeps, from which every registration "
            + "identifier is derived deterministically. Resending it returns the same tenant rather than creating a "
            + "second one — and a short key becomes guessable.");
        w.WriteEndObject();
    }

    /// <summary>السند على السلك — إلزامي على كل تغيير اشتراك.</summary>
    private static void WriteAuthorityProperty(Utf8JsonWriter w)
    {
        w.WriteStartObject("authority");
        w.WriteString("type", "string");
        w.WriteNumber("minLength", 1);
        w.WriteNumber("maxLength", 200);
        w.WriteString("description",
            "السند: رقم عقد، أو حدث سداد، أو تذكرة دعم، أو قرار مُوثَّق. **ولا تغيير استحقاق بلا سند**: "
            + "الاستحقاق يحكم أي بيانات مالية يجوز إنشاؤها، فتغييره حدث تدقيقي. / "
            + "The authority: a contract number, a payment event, a support ticket, or a documented decision. **No "
            + "entitlement change without authority**: entitlement governs which financial data may be created, so "
            + "changing it is an audit event.");
        w.WriteEndObject();
    }

    private static void WriteStringProperty(Utf8JsonWriter w, string name, string ar, string en, int maxLength)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteNumber("maxLength", maxLength);
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteNullableStringProperty(Utf8JsonWriter w, string name, string ar, string en, int maxLength)
    {
        w.WriteStartObject(name);
        w.WriteStartArray("type");
        w.WriteStringValue("string");
        w.WriteStringValue("null");
        w.WriteEndArray();
        w.WriteNumber("maxLength", maxLength);
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteBooleanProperty(Utf8JsonWriter w, string name, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "boolean");
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteIntegerProperty(Utf8JsonWriter w, string name, int minimum, int maximum, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "integer");
        w.WriteNumber("minimum", minimum);
        w.WriteNumber("maximum", maximum);
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteNullableIntegerProperty(Utf8JsonWriter w, string name, int minimum, int maximum, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteStartArray("type");
        w.WriteStringValue("integer");
        w.WriteStringValue("null");
        w.WriteEndArray();
        w.WriteNumber("minimum", minimum);
        w.WriteNumber("maximum", maximum);
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteEnumProperty(Utf8JsonWriter w, string name, string ar, string en, IReadOnlyList<string> members)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteStartArray("enum");
        foreach (string member in members)
        {
            w.WriteStringValue(member);
        }

        w.WriteEndArray();
        w.WriteString("description",
            ar + " يُطابَق حرفياً وبحساسية حالة الأحرف؛ ولا يُقبل رقم مكان الاسم. / "
            + en + " Matched literally and case-sensitively; a number is never accepted in place of a name.");
        w.WriteEndObject();
    }

    /// <summary>
    /// اعتمادٌ مبهم على السلك: <c>base64url</c> بلا حشو.
    /// <para>
    /// <b>ولا بنية فيه يقرؤها العميل</b> — لا مستأجر، ولا انقضاء، ولا توقيع. وذلك مقصود:
    /// اعتمادٌ يحمل دعاواه بنفسه يُصدَّق بالتحقق من توقيعه وحده، فيبقى صالحاً بعد الإبطال
    /// إلى أن ينقضي. والانقضاء والإبطال هنا حالةٌ تُقرأ من الخادم عند كل طلب، والاعتماد
    /// <b>مفتاحٌ لا وثيقة</b>.
    /// </para>
    /// </summary>
    private static void WriteCredentialProperty(Utf8JsonWriter w, string name, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteString("pattern", "^[A-Za-z0-9_-]{16,512}$");
        w.WriteNumber("maxLength", AccessLimits.MaximumPresentedLength);
        w.WriteString("description",
            ar + " نصٌّ مبهم لا بنية فيه: لا يُحلَّل ولا يُشتقّ منه شيء، ويُقدَّم كما وصل. / "
            + en + " An opaque string with no structure: never parsed, nothing derived from it, presented exactly as received.");
        w.WriteEndObject();
    }

    /// <summary>لحظةٌ على السلك: ‏ISO 8601 الدوّارة بتوقيت UTC وبأرقام لاتينية.</summary>
    private static void WriteInstantProperty(Utf8JsonWriter w, string name, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteString("format", "date-time");
        w.WriteString("description",
            ar + " بصيغة ISO 8601 الدوّارة بتوقيت UTC وبأرقام لاتينية — الصيغة نفسها التي يقرأ بها الخادم صلاحية "
            + "اعتماده من إعداده، فلا وقتٌ يُكتب بشكل ويُقرأ بآخر. / "
            + en + " In round-trip ISO 8601, UTC, Latin digits — the same spelling the server reads a credential expiry with "
            + "from its own configuration, so no instant is written one way and read another.");
        w.WriteEndObject();
    }

    private static void WriteRefProperty(Utf8JsonWriter w, string name, string schema)
    {
        w.WriteStartObject(name);
        w.WriteString("$ref", "#/components/schemas/" + schema);
        w.WriteEndObject();
    }

    private static void WriteArrayRefProperty(Utf8JsonWriter w, string name, string schema, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "array");
        WriteRef(w, "items", schema);
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteCurrencyProperty(Utf8JsonWriter w)
    {
        w.WriteStartObject("currency");
        w.WriteString("type", "string");
        w.WriteString("pattern", "^[A-Z]{3}$");
        w.WriteString("description",
            "رمز عملة ISO 4217 بثلاثة محارف لاتينية كبيرة. واللاتينية هنا شرط سلامة سلسلة التجزئة لا تفضيل عرض. / "
            + "An ISO 4217 currency code, three upper-case ASCII letters. ASCII here is a hash-chain safety requirement, not a display preference.");
        w.WriteEndObject();
    }

    private static void WriteDateProperty(Utf8JsonWriter w, string name, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$");
        w.WriteString("description",
            ar + " ميلادي بصيغة yyyy-MM-dd حصراً وبأرقام لاتينية؛ أي تقويم آخر يُقرأ فترة مالية مختلفة. / "
            + en + " Gregorian, yyyy-MM-dd only, Latin digits; any other calendar reads as a different fiscal period.");
        w.WriteEndObject();
    }

    /// <summary>
    /// تاريخ ميلادي <b>أو <c>null</c></b> — لحقلٍ غيابه واقعة لا نقص (علاقة عمل سارية
    /// لم تنتهِ بعد). ونشرُه نصّاً بلا نمط كان سيُسقط النمط الذي يمنع التقويم الآخر.
    /// </summary>
    private static void WriteNullableDateProperty(Utf8JsonWriter w, string name, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteStartArray("type");
        w.WriteStringValue("string");
        w.WriteStringValue("null");
        w.WriteEndArray();
        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$");
        w.WriteString("description",
            ar + " ميلادي بصيغة yyyy-MM-dd حصراً وبأرقام لاتينية. / "
            + en + " Gregorian, yyyy-MM-dd only, Latin digits.");
        w.WriteEndObject();
    }

    /// <summary>
    /// أنواع مكوّنات الأجر — <b>مجموعة مغلقة منشورة</b>: المكوّن إمّا يزيد الأجر وإمّا
    /// ينقصه، ولا ثالث يُحتسب في مسيّر.
    /// </summary>
    private static readonly string[] PayComponentKinds = ["deduction", "earning"];

    /// <summary>
    /// طرق التسوية المقبولة على مستندات الموارد البشرية — <b>مجموعة ضيّقة عمداً</b>.
    /// <para>
    /// وهي مؤهّلات دور تقرؤها خريطة الأدوار، لا رموز حسابات. والمؤهّل الوسيط الموجود في
    /// الخريطة <b>غير مقبول هنا</b> لأن قبوله يفترض جواب سؤال مفتوح على المالك: متى يقع
    /// قيد صرف الرواتب بالضبط — عند توليد ملفّ حماية الأجور أم عند تأكيد المصرف؟
    /// </para>
    /// </summary>
    private static readonly string[] SettlementMethodNames = ["bank", "cash"];

    /// <summary>سيناريوهات مخالصة نهاية الخدمة — <b>بأسماء المصفوفة نفسها</b>.</summary>
    private static readonly string[] EndOfServiceScenarioCodes = ["exact", "excess", "short"];

    /// <summary>أسباب الانحراف في تقرير مطابقة دفتر الموظف.</summary>
    private static readonly string[] DivergenceReasonCodes =
        ["amount_mismatch", "missing_in_control", "missing_in_subledger", "posting_unresolved"];

    private static void WritePeriodProperty(Utf8JsonWriter w, string name)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "string");
        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])$");
        w.WriteString("description",
            "رمز الفترة المالية yyyy-MM ميلادياً دائماً — لا يتغيّر بثقافة الخادم ولا بثقافة العميل. / "
            + "The fiscal period code yyyy-MM, always Gregorian — unaffected by server or client culture.");
        w.WriteEndObject();
    }

    private static void WriteNullablePeriodProperty(Utf8JsonWriter w, string name)
    {
        w.WriteStartObject(name);
        w.WriteStartArray("type");
        w.WriteStringValue("string");
        w.WriteStringValue("null");
        w.WriteEndArray();
        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])$");
        w.WriteString("description",
            "رمز الفترة المالية yyyy-MM ميلادياً، أو null حين يشمل الطلب كل الفترات. / "
            + "The fiscal period code yyyy-MM, or null when the request spans all periods.");
        w.WriteEndObject();
    }

    /// <summary>
    /// حمولة إيداع مرفق: <c>multipart/form-data</c> بجزءٍ للبايتات وجزأين نصّيين.
    /// <para>
    /// <b>والاسم المُعلَن ونوع المحتوى المُعلَن لا حقلين في الحمولة</b> بل ترويستا جزء
    /// البايتات نفسه — <c>filename</c> و<c>Content-Type</c> — وهو الشكل الطبيعي
    /// لـ<c>multipart</c>. وكلاهما <b>لا يُصدَّق</b>: النوع يأتي من البايتات بالشمّ،
    /// والاسم يُطهَّر بقائمة سماح ولا يشارك في بناء أي مسار.
    /// </para>
    /// </summary>
    private static void WriteDepositForm(Utf8JsonWriter w)
    {
        w.WriteStartObject("requestBody");
        w.WriteBoolean("required", true);
        w.WriteStartObject("content");
        w.WriteStartObject("multipart/form-data");

        w.WriteStartObject("schema");
        w.WriteString("type", "object");
        w.WriteString("description",
            "حمولة الإيداع. جزءٌ إلزامي اسمه content يحمل البايتات، وترويستاه filename و Content-Type هما "
            + "الاسم المُعلَن والنوع المُعلَن — ولا يُصدَّق أيّهما. وجزآن نصّيان اختياريان يربطان المرفق بمستنده. / "
            + "The deposit payload. One mandatory part named content carries the bytes, and its filename and "
            + "Content-Type headers are the declared name and declared type — neither is believed. Two optional text "
            + "parts link the attachment to its source document.");
        w.WriteStartObject("properties");

        w.WriteStartObject("content");
        w.WriteString("type", "string");
        w.WriteString("format", "binary");
        w.WriteString("description",
            "بايتات المرفق. السقف الافتراضي عشرون ميبي‌بايت، وما تجاوزه يُرفض بـ413 بجسم مشكلة لا باستثناء. / "
            + "The attachment bytes. The default cap is twenty mebibytes; beyond it the request is refused with 413 "
            + "and a problem body, never an exception.");
        w.WriteEndObject();

        WriteStringProperty(
            w,
            "sourceDocumentType",
            "رمز نوع المستند المصدر — يُرسل مع معرّفه أو لا يُرسل، ونصفُ ربطٍ يُرفض.",
            "The source document type code — sent together with its identifier or not at all; half a link is refused.",
            64);

        w.WriteStartObject("sourceDocumentId");
        w.WriteString("type", "string");
        w.WriteString("format", "uuid");
        w.WriteString("description",
            "معرّف المستند المصدر — يُرسل مع نوعه أو لا يُرسل. / "
            + "The source document identifier — sent together with its type or not at all.");
        w.WriteEndObject();

        w.WriteEndObject();
        WriteRequired(w, "content");
        w.WriteBoolean("additionalProperties", false);
        w.WriteEndObject();

        w.WriteEndObject();
        w.WriteEndObject();
        w.WriteEndObject();
    }

    /// <summary>
    /// خاصيّةٌ تُشير إلى مخطّط مسمّى <b>أو تكون <c>null</c></b>.
    /// <para>
    /// و<c>oneOf</c> لا <c>nullable</c>: الأخيرة كلمة من الإصدار 3.0 لا وجود لها في 3.1،
    /// وقارئٌ صارم يتجاهلها فيصير الحقل إلزامياً في نظره.
    /// </para>
    /// </summary>
    private static void WriteNullableRefProperty(Utf8JsonWriter w, string name, string schema, string ar, string en)
    {
        w.WriteStartObject(name);
        w.WriteStartArray("oneOf");
        w.WriteStartObject();
        w.WriteString("$ref", "#/components/schemas/" + schema);
        w.WriteEndObject();
        w.WriteStartObject();
        w.WriteString("type", "null");
        w.WriteEndObject();
        w.WriteEndArray();
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteRequired(Utf8JsonWriter w, params string[] names)
    {
        w.WriteStartArray("required");
        foreach (string name in names.OrderBy(static n => n, StringComparer.Ordinal))
        {
            w.WriteStringValue(name);
        }

        w.WriteEndArray();
    }

    private const string MoneyDescription =
        "مبلغ نصّاً، بمقياس لا يتجاوز أربع خانات عشرية. النحو المقبول كاملاً: -?(0|[1-9][0-9]*)(\\.[0-9]{1,4})? — "
        + "فتُرفض الصيغة الأسّية، والصفر البادئ، والإشارة الموجبة الصريحة، والفراغ، والأرقام العربية-الهندية والديفاناغارية، "
        + "وكل ما زاد على أربع خانات. ورمزٌ رقمي في هذا الحقل يُرفض الطلب بسببه: JSON لا يملك نوعاً عشرياً، "
        + "وأغلب العملاء يمرّرون الرمز الرقمي على فاصلة عائمة ثنائية فيقع فقدان الدقّة قبل أن يصل الطلب. / "
        + "An amount as a string with at most four decimal places. The full accepted grammar is -?(0|[1-9][0-9]*)(\\.[0-9]{1,4})? — "
        + "exponent notation, leading zeros, an explicit plus sign, whitespace, Arabic-Indic and Devanagari digits, and any fifth "
        + "decimal are all refused. A JSON number token in this field fails the request: JSON has no decimal type, and most clients "
        + "route a number token through a binary double, so precision is lost before the request arrives.";

    private const string ContractDescription =
        "العزل التام بين الواجهات والخلفية: هذه الوثيقة هي كل ما يحتاجه فريق الواجهة، ولا يقرأ شيفرة خلفية.\n\n"
        + "سياسة الإصدار — ما يبقى في v1 وما يفرض v2:\n"
        + "• يبقى في v1: إضافة نقطة نهاية · إضافة حقل اختياري في استجابة · إضافة حقل اختياري في طلب له افتراض معلن · "
        + "إضافة عضو إلى تعداد يُقرأ من الخادم إلى العميل · إضافة رمز خطأ جديد · توسيع مدى مسموح · تحسين نصّ وصف أو رسالة.\n"
        + "• يفرض v2: حذف حقل أو نقطة نهاية · إعادة تسمية أي منهما · تضييق نوع أو مدى أو نمط · جعل حقل اختياري إلزامياً · "
        + "تغيير معنى رمز خطأ قائم أو رمز الحالة الذي يصحبه · إزالة عضو من تعداد يُرسله العميل · تغيير الافتراض المعلن لحقل.\n"
        + "• والقاعدة الحاكمة: تغييرٌ يجعل عميلاً مطابقاً للعقد القديم يعمل خطأً — لا يفشل، بل يعمل خطأً — هو v2 دائماً.\n"
        + "• ونطاق هذه السياسة: **تلزم من أول نشر للعقد فصاعداً**. غرضها حماية عميل مطابق قائم، فحيث لا عميل "
        + "لا شيء تحميه — ويبقى تعديل v1 في مكانه جائزاً ما دامت الوثيقة لم تُنشر لأي مستهلك، بشرط أن يُسجَّل "
        + "التعديل بتاريخه وسببه في سجل القرارات لا أن يمرّ صامتاً.\n"
        + "• تعديل مُسجَّل — 2026-08-24: صار الحقل event إلزامياً في PostJournalEntryRequest. وهو تضييق يفرض v2 "
        + "بنصّ السياسة، ونُفِّذ في v1 في مكانه لأن العقد لم يُنشر بعد لأي مستهلك ولا يوجد عميل مطابق واحد. "
        + "السبب: رمز الحدث جزء من هوية الترحيل، وغيابه يبتلع حدثاً محاسبياً بصمت (ADR-0016 · ADR-0018).\n"
        + "• تعديل مُسجَّل — 2026-08-26: حُذف الحقل nameEn من TrialBalanceRow. وهو حذف حقل يفرض v2 بنصّ السياسة، "
        + "ونُفِّذ في v1 في مكانه للسبب نفسه: لا مستهلك ولا عميل مطابق. السبب: تعدّد اللغات قابلية الترجمة إلى "
        + "أيّ عدد من اللغات، والإنجليزية واحدة من N لا نصف الاثنين — وحقلٌ ثابت لها على السلك يمنحها امتيازاً "
        + "بنيوياً ينفيه القرار، ويجعل المحاسب الأردي أو الهندي يقرأ إنجليزيةً بدل لغته. وnameTranslations "
        + "يحمل كل لغة بما فيها الإنجليزية (ADR-0021 بند 2 · ADR-0018).\n"
        + "• تعديل مُسجَّل — 2026-08-26: ضاق نوع Scope.costCenterId من [string, null] إلى string. وهو تضييق نوع "
        + "يفرض v2 بنصّ السياسة، ونُفِّذ في v1 في مكانه للسبب نفسه: لا مستهلك ولا عميل مطابق. الحقل يبقى "
        + "**اختيارياً** — حذفه يعني المركز الافتراضي للمنشأة — لكن القيمة null لا معنى لها: لكل منشأة مركز "
        + "تكلفة واحد على الأقل ولا سطر بلا مركز، فـnull كان يقول «بلا مركز» وهي حالة لا وجود لها. "
        + "والقيد ck_journal_line_cost_center_present يفرض ذلك في قاعدة البيانات نفسها (ADR-0026 · ADR-0018).\n\n"
        + "Total isolation between front end and back end: this document is everything a front-end team needs; it reads no back-end code.\n\n"
        + "Versioning policy — what stays in v1 and what forces v2:\n"
        + "• Stays in v1: adding an endpoint; adding an optional response field; adding an optional request field with a published default; "
        + "adding a member to a server-to-client enum; adding a new error code; widening an allowed range; improving a description or message.\n"
        + "• Forces v2: removing a field or endpoint; renaming either; narrowing a type, range, or pattern; making an optional field required; "
        + "changing the meaning of an existing error code or the status that accompanies it; removing a member from a client-to-server enum; "
        + "changing a field's published default.\n"
        + "• The governing rule: a change that makes a client conforming to the old contract behave wrongly — not fail, but behave wrongly — is always v2.\n"
        + "• Scope of this policy: **it binds from the contract's first publication onward**. Its purpose is to protect an existing "
        + "conforming client, so where there is no client there is nothing to protect — and amending v1 in place remains legitimate "
        + "while the document has not been published to any consumer, provided the amendment is recorded with its date and reason in "
        + "the decision record rather than passing silently.\n"
        + "• Recorded amendment — 2026-08-24: the event field became required on PostJournalEntryRequest. That is a narrowing which the "
        + "policy text forces to v2, and it was made in v1 in place because the contract has not yet been published to any consumer and "
        + "no conforming client exists. Reason: the event code is part of the posting identity, and its absence swallows an accounting "
        + "event silently (ADR-0016, ADR-0018).\n"
        + "• Recorded amendment — 2026-08-26: the nameEn field was removed from TrialBalanceRow. Removing a field is a change the policy "
        + "text forces to v2, and it was made in v1 in place for the same reason: no consumer and no conforming client. Reason: "
        + "multilingualism means translatability into any number of languages, and English is one of N rather than half of two — a fixed "
        + "field for it on the wire grants it a structural privilege the decision denies, and leaves an Urdu or Hindi accountant reading "
        + "English instead of their own language. nameTranslations carries every language, English included (ADR-0021 clause 2, ADR-0018).\n"
        + "• Recorded amendment — 2026-08-26: the type of Scope.costCenterId narrowed from [string, null] to string. Narrowing a type is a "
        + "change the policy text forces to v2, and it was made in v1 in place for the same reason: no consumer and no conforming client. "
        + "The field stays **optional** — omitting it means the company's default centre — but the value null has no meaning: every company "
        + "has at least one cost centre and no line is without one, so null said 'no centre', a state that does not exist. The constraint "
        + "ck_journal_line_cost_center_present enforces this in the database itself (ADR-0026, ADR-0018).";

    private sealed record Operation(
        string Path,
        string Method,
        string OperationId,
        string SummaryAr,
        string SummaryEn,
        string DescriptionAr,
        string DescriptionEn,
        string? Body,
        string Response,
        int Success,
        IReadOnlyList<QueryParameter> Query,

        // نوع محتوى الاستجابة الناجحة. الافتراضي application/json بمرجع $ref إلى مخطّط
        // مسمّى — وهو حال كل عملية أعمال، ولذلك لم تتغيّر بايتة واحدة منها بإضافة هذين
        // الوسيطين. والبابان الوحيدان اللذان يخالفانه يخدمان ملفَّين ساكنَين لا نموذجَي
        // مجال، فلا مخطّط لهما يُسمّى.
        string ResponseMediaType = "application/json",

        // شكل الاستجابة حين لا تكون مخطّطاً مسمّى: object أو string.
        string? ResponseInlineType = null,

        // صيغة الشكل المضمَّن — `binary` وحدها اليوم، لبابٍ يخدم بايتات ملفّ لا JSON.
        string? ResponseInlineFormat = null,

        // ‏**حمولة الإيداع متعدّدة الأجزاء لا JSON** (ADR-0046 §8 شرط 1): جسم JSON يعني
        // ترميز البايتات نصّاً، أي انتفاخ الثلث وصورةً كاملة في سجلّ الطلب. والمخطّط
        // يُكتب **مضمَّناً** لا مخطّطاً مسمّى: مخطّطٌ باسمٍ كان سيُولِّد في العميل
        // واجهةً حقلُها `content: string` — وهي كذبة عن حقلٍ بايتاته ملفّ.
        bool DepositForm = false,

        // رموز مشكلات إضافية تُوثَّق على هذه العملية وحدها.
        //
        // **ولماذا لكل عملية لا بقاعدة عامة:** الرموز التي تُكتب تلقائياً (401 و403 على
        // كل ما يحتاج اعتماداً، و400 و409 و422 على كل ما له جسم) تُشتقّ من شكل العملية
        // نفسه فلا تكذب. أمّا 404 فيعتمد على **ما إذا كان المورد يُعنون شيئاً قائماً** —
        // وهي معلومة لا يحملها شكل العملية. وقاعدةٌ عامة تكتب 404 على كل مسار فيه {id}
        // كانت ستكتبه على مساراتٍ لا تُرجعه أبداً، فيبني عليه عميل معالجةً لحالة لا تقع.
        IReadOnlyList<int>? ProblemStatuses = null,
        // ‏**رفوضٌ مُعلَنة بأعيانها** بدل الطقم الافتراضي (400 · 409 · 422) الذي يُضاف لكل
        // عملية ذات جسم. والافتراضي باقٍ كما هو — القيمة null هنا تعني «كما كان» فلم تتغيّر
        // بايتة واحدة من العمليات القائمة — وما يُعلن هنا يُكتب حرفياً.
        //
        // ولماذا وُجد أصلاً: بابا الجلسة يَقبلان جسماً ولا يُرجعان 409 ولا 422 أبداً،
        // ويُرجعان 401 وهما **بلا مصادقة** (الاعتماد في الجسم لا في الترويسة). فالطقم
        // الافتراضي كان سيصف بابين بما لا يفعلانه ويسكت عمّا يفعلانه — وعقدٌ يصف رفضاً
        // لا يقع أسوأ من عقدٍ ساكت: يُبنى عليه فرعٌ لا يُنفَّذ أبداً.
        IReadOnlyList<Refusal>? Refusals = null,

        // ‏**استجاباتُ نجاحٍ إضافية على العملية نفسها** — بمخطّطها هي، لا بمخطّط مشكلة.
        // ولماذا وُجدت: عمليةٌ **حصينة ضد التكرار** تُرجع 200 بدل 201 عند الإعادة، وذلك
        // نجاحٌ لا رفض. وكان ذلك مكتوباً بقائمة أسماء عمليات ونصٍّ واحد يصف الترحيل؛
        // ونصُّ الترحيل لا يصف تسجيلاً، فلو أُعيد استعماله لوصف العقدُ باباً بما لا يفعله.
        IReadOnlyList<Refusal>? Repeats = null)
    {
    /// <summary>
    /// هل هذه العملية بابٌ مفتوح؟ — <b>مقروءةً من القائمة الواحدة، لا مكتوبةً هنا</b>.
    /// <para>
    /// وكانت وسيطاً يُكتب على كل عملية، فكانت «أي المسارات تُفتح بلا اعتماد؟» مُعلَنةً
    /// في موضعين: هنا وفي وسيط المصادقة. وقد رُبطا بحارسٍ يطرق كل باب في العقد ويقارن
    /// جواب الخادم بما وعد به، والحارس باقٍ — لكنه يمسك الانحراف <b>بعد وقوعه</b>.
    /// والقائمة الآن واحدة في <see cref="OpenDoors"/>، ويقرؤها الطرفان.
    /// </para>
    /// </summary>
    public bool Anonymous => OpenDoors.IsOpen(Path);
}

    /// <summary>رفضٌ مُعلَن على عملية بعينها: رمزه ووصفه بلغتيه.</summary>
    private sealed record Refusal(int Status, string Ar, string En);

    private sealed record QueryParameter(string Name, bool Required, string DescriptionAr, string DescriptionEn, string Kind);
}
